import type { QuestionBank } from './types';

type Q = QuestionBank['questions'][number];

const CID = 'film-school';

/** mcq builder: lesson id, number, level, prompt, choices, answer index, hint, explanation. */
let mcqCount = 0;
const m = (l: string, n: number, level: 1 | 2 | 3, prompt: string, choices: string[], answer: number, hint: string, explanation: string): Q => {
  // Spread the correct index evenly across 0-3 by rotating the choice order (deterministic).
  const target = (mcqCount++ * 3 + (mcqCount % 5)) % 4;
  const shift = (answer - target + choices.length) % choices.length;
  const rotated = choices.map((_, i) => choices[(i + shift) % choices.length]);
  return { id: `${CID}.${l}.q${n}`, lessonId: l, kind: 'mcq', prompt, choices: rotated, answer: target, hint, explanation, level };
};
/** true/false builder: answer 0 = True, 1 = False. */
const t = (l: string, n: number, level: 1 | 2 | 3, prompt: string, answer: 0 | 1, hint: string, explanation: string): Q => ({
  id: `${CID}.${l}.q${n}`, lessonId: l, kind: 'tf', prompt, answer, hint, explanation, level,
});

